APP_HTML = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>meld — timed bridge</title>\n<!--MELD_PREVIEW-->\n<style>\n:root{\n  --bg:#10141c;--panel:#181e2a;--panel-2:#202838;--ink:#eef3fb;--muted:#a9b4c6;\n  --line:#313a4d;--accent:#7ee0c6;--accent-ink:#06241c;--warn:#f3d48a;--warn-bg:#3a2e14;\n  --danger:#ffb4a8;--ok:#b6f3df;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 "Segoe UI",ui-sans-serif,sans-serif}\na{color:var(--accent)}\nbutton,input,textarea{font:inherit}\n.app{max-width:1080px;margin:0 auto;padding:1.25rem 1.1rem 3rem}\n.top{display:flex;justify-content:space-between;gap:1rem;align-items:baseline;margin-bottom:1.25rem}\n.brand{font-weight:700;letter-spacing:.04em}\n.brand span{color:var(--muted);font-weight:500}\n.top nav{font-size:.85rem;color:var(--muted)}\n.top nav a{color:var(--muted);margin-left:.75rem}\n.layout{display:grid;grid-template-columns:240px 1fr;gap:1rem;align-items:start}\n.rail,.panel{background:var(--panel);border:1px solid var(--line);border-radius:16px}\n.rail{padding:1rem}\n.rail.off{display:none !important}\n.rail h2,.panel h2{margin:0 0 .75rem;font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.step{display:flex;gap:.7rem;padding:.65rem 0;border-top:1px solid var(--line);color:var(--muted)}\n.step:first-of-type{border-top:0}\n.step.on{color:var(--ink)}\n.step.done .n{background:var(--accent);color:var(--accent-ink)}\n.n{flex:0 0 auto;width:1.6rem;height:1.6rem;border-radius:99px;display:grid;place-items:center;border:1px solid var(--line);font-size:.8rem}\n.step.on .n{border-color:var(--accent);color:var(--accent)}\n.step small{display:block;color:var(--muted);font-size:.78rem}\n.panel{padding:1.15rem 1.2rem 1.25rem}\nh1{font-size:1.7rem;line-height:1.15;margin:.1rem 0 .45rem}\n.lede{color:var(--muted);margin:0 0 1rem}\n.needs{display:grid;grid-template-columns:1fr 1fr;gap:.6rem;margin:0 0 1rem}\n.need{background:var(--panel-2);border-radius:12px;padding:.75rem .8rem}\n.need b{display:block;font-size:.92rem}\n.need span{display:block;color:var(--muted);font-size:.82rem;margin-top:.15rem}\nlabel{display:block;font-weight:650;margin:.2rem 0 .35rem}\ntextarea{width:100%;min-height:180px;resize:vertical;padding:.85rem;border-radius:12px;border:1px solid var(--line);background:#0e131c;color:var(--ink)}\ntextarea:focus,button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n.hint{color:var(--muted);font-size:.82rem;margin:.35rem 0 .9rem}\n.times{display:grid;grid-template-columns:repeat(3,1fr);gap:.55rem}\n.time{text-align:left;padding:.8rem;border-radius:12px;border:1px solid var(--line);background:#0e131c;color:var(--ink);cursor:pointer}\n.time b{display:block;font-size:1.02rem}\n.time span{display:block;color:var(--muted);font-size:.78rem;margin-top:.2rem}\n.time[aria-checked="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}\n.time[aria-checked="true"] span{color:#24584a}\n.trust{margin:1rem 0;padding:.8rem .9rem;border-radius:12px;background:var(--warn-bg);color:var(--warn)}\n.trust strong{color:#ffe7ad}\n.trust ul{margin:.35rem 0 0;padding-left:1.1rem}\n.trust li{margin:.15rem 0}\n.actions{display:flex;gap:.7rem;align-items:center;flex-wrap:wrap}\nbutton.primary{background:var(--accent);color:var(--accent-ink);border:0;border-radius:999px;padding:.75rem 1.1rem;font-weight:700;cursor:pointer}\nbutton.primary:disabled{opacity:.55;cursor:wait}\nbutton.ghost{background:transparent;color:var(--ink);border:1px solid var(--line);border-radius:999px;padding:.65rem .95rem;cursor:pointer}\n.status{color:var(--muted);min-height:1.2rem}\n.status.bad{color:var(--danger)}\n.box{margin:.7rem 0;padding:.9rem;border-radius:12px;background:#0e131c;border:1px solid var(--line);white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.45 ui-monospace,monospace}\na.url{display:block;font-size:1rem;color:var(--ok);text-decoration:none}\n.meta{color:var(--muted);font-size:.9rem}\n.count{float:right;color:var(--muted);font-weight:500;font-size:.8rem}\n@media(max-width:800px){\n  .layout{grid-template-columns:1fr}\n  .needs,.times{grid-template-columns:1fr}\n  .rail{display:flex;gap:.4rem;overflow:auto}\n  .step{border-top:0;min-width:9.5rem}\n}\n</style>\n</head>\n<body>\n<div class="app">\n  <header class="top">\n    <div class="brand">meld <span>timed bridge</span></div>\n    <nav><a href="/">New bridge</a><a href="/agents">Agent API</a><a href="/trust">Trust</a><a href="/llms.txt">llms.txt</a></nav>\n  </header>\n  <div class="layout">\n    <aside class="rail" id="creator-rail" aria-label="Task steps">\n      <h2>This task</h2>\n      <div class="step on" id="s1"><div class="n">1</div><div>Write the handoff<small>What the other side must read</small></div></div>\n      <div class="step" id="s2"><div class="n">2</div><div>Choose the time<small>3 minutes, 1 hour, or 1 day</small></div></div>\n      <div class="step" id="s3"><div class="n">3</div><div>Share the link<small>The link is the bearer</small></div></div>\n      <div class="step" id="s4"><div class="n">4</div><div>Read the reply<small>Same link, until it expires</small></div></div>\n    </aside>\n    <aside class="rail off" id="receiver-rail" aria-label="Your job">\n      <h2>Your job</h2>\n      <div class="step on" id="r1"><div class="n">1</div><div>Read<small>What they sent on this link</small></div></div>\n      <div class="step" id="r2"><div class="n">2</div><div>Reply<small>Put your answer on this link</small></div></div>\n      <div class="step" id="r3"><div class="n">3</div><div>Done<small>Both sides stay until the timer ends</small></div></div>\n    </aside>\n    <main class="panel" id="root"></main>\n  </div>\n</div>\n<script>\nconst API = location.origin;\nlet code = null;\nlet picked = "";\nlet watching = false;\nlet watchTimer = null;\n// One read every 10s is 6/min, under the 60/min view limit. No new auth.\nconst esc = s => { const d = document.createElement("div"); d.textContent = s ?? ""; return d.innerHTML; };\nasync function api(method, path, body, headers = {}) {\n  const r = await fetch(API + path, {\n    method,\n    headers: { "Content-Type": "application/json", "X-Meld-Client": "human", ...headers },\n    body: body ? JSON.stringify(body) : undefined\n  });\n  const d = await r.json().catch(() => ({ detail: r.statusText }));\n  if (!r.ok) throw Error(d.detail || String(r.status));\n  return d;\n}\nfunction setSteps(active) {\n  document.getElementById("creator-rail").classList.remove("off");\n  document.getElementById("receiver-rail").classList.add("off");\n  for (let i = 1; i <= 4; i++) {\n    const el = document.getElementById("s" + i);\n    el.classList.toggle("on", i === active);\n    el.classList.toggle("done", i < active || active > 4);\n  }\n}\nfunction setReceiverJob(active) {\n  document.getElementById("creator-rail").classList.add("off");\n  document.getElementById("receiver-rail").classList.remove("off");\n  for (let i = 1; i <= 3; i++) {\n    const el = document.getElementById("r" + i);\n    el.classList.toggle("on", i === active);\n    el.classList.toggle("done", i < active || active > 3);\n  }\n}\nfunction trustBlock(forOpener) {\n  const last = forOpener\n    ? "The bridge dissolves when its timer runs out. Then the link is gone."\n    : "The bridge dissolves when the timer you choose runs out. Then the link is gone.";\n  return \'<div class="trust"><strong>Read this before you put text on the bridge.</strong><ul>\'\n    + "<li>The link is the bearer. Anyone who has it can read the exchange while it is live.</li>"\n    + "<li>The host can read it while it is live.</li>"\n    + "<li>Not for secrets, credentials, or regulated data.</li>"\n    + "<li>" + last + "</li>"\n    + "</ul></div>";\n}\nfunction needsBlock() {\n  return \'<div class="needs">\'\n    + \'<div class="need"><b>The handoff</b><span>The working context the other person or agent should read.</span></div>\'\n    + \'<div class="need"><b>A bridge time</b><span>Only three: 3 minutes, 1 hour, or 1 day.</span></div>\'\n    + \'<div class="need"><b>The capability URL</b><span>Sharing the link is what lets the other side in.</span></div>\'\n    + \'<div class="need"><b>A reply on that link</b><span>They open it, answer, and you read the reply here.</span></div>\'\n    + "</div>";\n}\nfunction landing() {\n  stopWatch();\n  document.title = "meld — timed bridge";\n  setSteps(1);\n  root.innerHTML = \'<h1>Open a timed bridge</h1>\'\n    + \'<p class="lede">Hand one piece of working context to another person or agent. You get a capability URL. That URL is the shared bearer for the exchange, and it dies on the timer you pick.</p>\'\n    + needsBlock()\n    + \'<label for="ctx">1. Context the other side must read <span class="count" id="count">0 / 100000</span></label>\'\n    + \'<textarea id="ctx" placeholder="Decisions, constraints, and the next step they need. Ordinary working context only."></textarea>\'\n    + \'<p class="hint">This text is what they see when they open the link. Leave out secrets.</p>\'\n    + \'<label id="time-label">2. How long should this bridge stay live?</label>\'\n    + \'<div class="times" role="radiogroup" aria-labelledby="time-label">\'\n    + timeBtn("3m", "3 minutes", "For a quick handoff. Dissolves in 3 minutes.")\n    + timeBtn("1hr", "1 hour", "For a working session. Dissolves in 1 hour.")\n    + timeBtn("1d", "1 day", "For a handoff that can wait. Dissolves in 1 day.")\n    + "</div>"\n    + \'<p class="hint" id="time-hint">Choose one. Nothing is selected until you do. There is no other duration.</p>\'\n    + trustBlock()\n    + \'<div class="actions"><button class="primary" id="create" type="button">Create the bridge</button><span class="status" id="status" role="status"></span></div>\';\n  const ctx = document.getElementById("ctx");\n  const count = document.getElementById("count");\n  ctx.addEventListener("input", () => {\n    count.textContent = ctx.value.length + " / 100000";\n    setSteps(ctx.value.trim() && picked ? 3 : ctx.value.trim() ? 2 : 1);\n  });\n  document.querySelectorAll(".time").forEach(btn => {\n    btn.addEventListener("click", () => selectTime(btn.dataset.ttl));\n  });\n  document.getElementById("create").addEventListener("click", createBridge);\n}\nfunction timeBtn(ttl, title, detail) {\n  return \'<button type="button" class="time" role="radio" data-ttl="\' + ttl + \'" aria-checked="false"><b>\' + title + \'</b><span>\' + detail + \'</span></button>\';\n}\nfunction selectTime(ttl) {\n  picked = ttl;\n  document.querySelectorAll(".time").forEach(btn => btn.setAttribute("aria-checked", btn.dataset.ttl === ttl ? "true" : "false"));\n  const labels = { "3m": "3 minutes", "1hr": "1 hour", "1d": "1 day" };\n  document.getElementById("time-hint").textContent = "Selected: " + labels[ttl] + ". The server will dissolve this bridge on that timer.";\n  const ctx = document.getElementById("ctx");\n  setSteps(ctx && ctx.value.trim() ? 3 : 2);\n}\nasync function createBridge() {\n  const ctx = document.getElementById("ctx");\n  const status = document.getElementById("status");\n  const button = document.getElementById("create");\n  const text = ctx.value;\n  status.classList.remove("bad");\n  if (!text.trim()) {\n    status.classList.add("bad");\n    status.textContent = "Add the context the other side must read.";\n    ctx.focus();\n    return;\n  }\n  if (!picked) {\n    status.classList.add("bad");\n    status.textContent = "Choose a bridge time: 3 minutes, 1 hour, or 1 day.";\n    return;\n  }\n  button.disabled = true;\n  status.textContent = "Creating the bridge…";\n  try {\n    const d = await api("POST", "/api/melds", { context: text, ttl: picked });\n    code = d.code;\n    showCreated(d);\n  } catch (e) {\n    status.classList.add("bad");\n    status.textContent = e.message;\n    button.disabled = false;\n  }\n}\nfunction showCreated(d) {\n  document.title = "meld — bridge is live";\n  setSteps(3);\n  const when = d.expires_at ? new Date(d.expires_at).toLocaleString() : "the timer you chose";\n  root.innerHTML = \'<h1>Share this capability URL</h1>\'\n    + \'<p class="lede">Send this link to the other person or agent. The link is the bearer: whoever has it can read the live exchange and write the reply.</p>\'\n    + \'<a class="box url" id="share" href="\' + esc(d.url) + \'">\' + esc(d.url) + \'</a>\'\n    + \'<p class="meta">Bridge time: <b>\' + esc(ttlLabel(d.ttl || picked)) + \'</b> · dissolves \' + esc(when) + \'</p>\'\n    + \'<div class="needs">\'\n    + \'<div class="need"><b>You do this</b><span>Copy the URL and send it to the other side.</span></div>\'\n    + \'<div class="need"><b>They do this</b><span>Open the link, read your context, and write a reply.</span></div>\'\n    + \'<div class="need"><b>Then you</b><span>Stay on this page. It watches for the reply.</span></div>\'\n    + \'<div class="need"><b>Then it ends</b><span>When the timer hits, the bridge dissolves.</span></div>\'\n    + \'</div>\'\n    + trustBlock()\n    + \'<div class="actions"><button class="ghost" id="copy" type="button">Copy link</button><button class="primary" id="check" type="button">Check for the reply</button><span class="status" id="status" role="status"></span></div>\'\n    + \'<div id="result"></div>\';\n  document.getElementById("copy").onclick = copyLink;\n  document.getElementById("check").onclick = () => checkResult(false);\n  startWatch();\n}\nfunction ttlLabel(ttl) {\n  return { "3m": "3 minutes", "1hr": "1 hour", "1d": "1 day" }[ttl] || ttl;\n}\nasync function copyLink() {\n  const url = document.getElementById("share").textContent;\n  const status = document.getElementById("status");\n  try {\n    await navigator.clipboard.writeText(url);\n    status.classList.remove("bad");\n    status.textContent = "Link copied.";\n  } catch (e) {\n    status.classList.add("bad");\n    status.textContent = "Select the link and copy it.";\n  }\n}\nfunction stopWatch() {\n  watching = false;\n  if (watchTimer) {\n    clearTimeout(watchTimer);\n    watchTimer = null;\n  }\n}\nfunction startWatch() {\n  watching = true;\n  checkResult(true);\n}\nfunction scheduleWatch(delay) {\n  if (!watching) return;\n  if (watchTimer) clearTimeout(watchTimer);\n  watchTimer = setTimeout(() => checkResult(true), delay);\n}\nasync function checkResult(quiet) {\n  const status = document.getElementById("status");\n  const result = document.getElementById("result");\n  if (!status || !result) {\n    stopWatch();\n    return;\n  }\n  if (!quiet) status.textContent = "Checking this bridge…";\n  try {\n    const d = await api("GET", "/api/melds/" + code);\n    const waiting = !d.context_b;\n    result.innerHTML = \'<div class="box"><b>Your context</b>\\n\' + esc(d.context_a)\n      + \'\\n\\n<b>Their reply</b>\\n\' + esc(d.context_b || "No reply yet. The bridge is still live.") + "</div>";\n    if (waiting) {\n      setSteps(4);\n      status.classList.remove("bad");\n      status.textContent = "Watching for a reply.";\n      scheduleWatch(10000);\n    } else {\n      setSteps(5);\n      status.textContent = "Reply is on the link. The bridge still dissolves on the timer.";\n      stopWatch();\n    }\n  } catch (e) {\n    const msg = e.message || "";\n    const limited = /too many|429/i.test(msg);\n    const gone = /expired|410|not found|404|unavailable/i.test(msg);\n    if (limited && watching) {\n      status.classList.remove("bad");\n      status.textContent = "Watching for a reply. Slowing down.";\n      scheduleWatch(45000);\n      return;\n    }\n    status.classList.add("bad");\n    status.textContent = msg;\n    if (watching && !gone) scheduleWatch(20000);\n    else stopWatch();\n  }\n}\nfunction meldPage() {\n  stopWatch();\n  document.title = "meld — this bridge expires";\n  code = decodeURIComponent(location.pathname.slice(3).split("/")[0]);\n  setReceiverJob(1);\n  root.innerHTML = "<h1>Opening this bridge…</h1><p class=\'status\' id=\'status\'>Loading the live exchange.</p>";\n  api("GET", "/api/melds/" + code).then(d => {\n    if (d.resolved && d.context_b) resolved(d);\n    else receiver(d);\n  }).catch(e => {\n    root.innerHTML = "<h1>This bridge is unavailable</h1><p>" + esc(e.message) + "</p><p class=\'lede\'>It may have dissolved on its timer. This preview never included the exchange.</p><p><a href=\'/\'>Open a new bridge</a></p>";\n  });\n}\nfunction remainingText(d) {\n  if (typeof d.seconds_remaining === "number") {\n    const s = d.seconds_remaining;\n    if (s < 90) return s + " seconds left";\n    if (s < 7200) return Math.round(s / 60) + " minutes left";\n    return Math.round(s / 3600) + " hours left";\n  }\n  return d.expires_at ? ("dissolves " + new Date(d.expires_at).toLocaleString()) : "dissolves on its timer";\n}\nfunction receiver(d) {\n  document.title = "meld — this bridge expires";\n  setReceiverJob(2);\n  root.innerHTML = "<h1>Reply on this bridge</h1>"\n    + "<p class=\'lede\'>Read what they sent, write the reply, and you are done. " + esc(remainingText(d)) + ".</p>"\n    + "<label>What they sent</label><div class=\'box\'>" + esc(d.context_a) + "</div>"\n    + "<label for=\'answer\'>Your reply</label><textarea id=\'answer\' placeholder=\'The answer they asked for. Ordinary working context only.\'></textarea>"\n    + trustBlock(true)\n    + "<div class=\'actions\'><button class=\'primary\' id=\'resolve\' type=\'button\'>Put the reply on this link</button><span class=\'status\' id=\'status\' role=\'status\'></span></div>";\n  document.getElementById("resolve").onclick = async () => {\n    const answer = document.getElementById("answer");\n    const status = document.getElementById("status");\n    const button = document.getElementById("resolve");\n    if (!answer.value.trim()) {\n      status.classList.add("bad");\n      status.textContent = "Write the reply first.";\n      answer.focus();\n      return;\n    }\n    button.disabled = true;\n    status.classList.remove("bad");\n    status.textContent = "Sending the reply…";\n    try {\n      const out = await api("POST", "/api/melds/" + code + "/resolve", { context: answer.value });\n      resolved(out);\n    } catch (e) {\n      status.classList.add("bad");\n      status.textContent = e.message;\n      button.disabled = false;\n    }\n  };\n}\nfunction resolved(d) {\n  document.title = "meld — this bridge expires";\n  setReceiverJob(4);\n  root.innerHTML = "<h1>Both sides are on the link</h1>"\n    + "<p class=\'lede\'>The exchange stays readable by anyone with this link until the timer ends. Then it dissolves.</p>"\n    + "<div class=\'box\'><b>Context</b>\\n" + esc(d.context_a) + "\\n\\n<b>Reply</b>\\n" + esc(d.context_b) + "</div>"\n    + trustBlock()\n    + "<p><a href=\'/\'>Open another bridge</a></p>";\n}\ndocument.addEventListener("visibilitychange", () => {\n  if (!watching) return;\n  if (document.hidden) {\n    if (watchTimer) {\n      clearTimeout(watchTimer);\n      watchTimer = null;\n    }\n  } else {\n    scheduleWatch(1000);\n  }\n});\nconst path = location.pathname;\nif (path.startsWith("/m/")) meldPage();\nelse landing();\n</script>\n</body>\n</html>\n'
